{
  description = "HackTheBurgh 2026: Next.js web app and uv Python data tools";

  inputs.nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

  outputs =
    { self, nixpkgs }:
    let
      systems = [
        "x86_64-linux"
        "aarch64-linux"
        "x86_64-darwin"
        "aarch64-darwin"
      ];
      forEachSystem = f: nixpkgs.lib.genAttrs systems (system: f nixpkgs.legacyPackages.${system});
    in
    {
      formatter = forEachSystem (pkgs: pkgs.nixfmt-rfc-style);

      devShells = forEachSystem (
        pkgs:
        let
          # nodejs_24 matches the Node version the app is developed on, and is
          # the version next 16 expects.
          node = pkgs.nodejs_24;
        in
        {
          default = pkgs.mkShell {
            packages = [
              node
              # pnpm_10 rather than the default pnpm 12: the repo pins
              # packageManager pnpm@10.32.1, and pnpm 12 rewrites the lockfile.
              pkgs.pnpm_10
              pkgs.uv
              # python314 matches tools/.python-version.
              pkgs.python314
              pkgs.jq
              pkgs.curl
              pkgs.gnumake
              pkgs.gcc
              pkgs.pkg-config
            ];

            env = {
              # Let pnpm run without corepack prompting to download itself.
              COREPACK_ENABLE_DOWNLOAD_PROMPT = "0";
              # Use the interpreter in this shell instead of letting uv download one.
              UV_PYTHON_PREFERENCE = "only-system";
            };

            shellHook = ''
              echo "htb-2026 dev shell"
              echo "  web:   cd web && pnpm install && pnpm dev"
              echo "  tools: cd tools && uv sync && uv run python -m tools.census"
              echo "         needs CENSUS_API_KEY in tools/.env (see tools/.env.example)"
              if [ ! -f tools/.env ]; then
                echo "  note: tools/.env is missing, so the Census script cannot run"
              fi
            '';
          };
        }
      );
    };
}

